  const mutationLock=useRef(false),dialogRef=useRef<HTMLDivElement>(null),lastJobId=useRef(job.id)
  const scene=job.scenes.find(item=>item.id===selectedId)||job.scenes[0],index=job.scenes.findIndex(item=>item.id===scene?.id)
  const feedback=scene?feedbackByScene[scene.id]||{reasons:[],note:'',instruction:'',candidateAdopted:false}:{reasons:[],note:'',instruction:'',candidateAdopted:false}
  const setFeedback=(value:VideoFeedback)=>{if(scene)setFeedbackByScene(current=>({...current,[scene.id]:value}))}
