  const fieldsChanged=(item:VideoScene)=>Boolean(edits[item.id]&&!sameSceneFields(edits[item.id],sceneFields(item,readVideoShotTextState(item))))
  const changed=(item:VideoScene)=>fieldsChanged(item)||hasVideoFeedback(feedbackByScene[item.id])
  const dirty=job.scenes.some(changed),sceneDirty=Boolean(scene&&changed(scene)),generating=['queued','generating','assembling'].includes(job.status),timeline=job.generationMode==='timeline'
  const awaitingReceipt=job.id.startsWith('pending_video_')
