  const canSaveScene=canEditScene&&textState.kind==='canonical'
  const canSaveText=canEditScene&&job.shotTextCapabilities?.actions.includes('save_shot_text')===true&&textState.kind==='canonical'
  const canClassify=canEditScene&&job.shotTextCapabilities?.actions.includes('classify_legacy_text')===true&&textState.kind==='legacy_unverified'
  const showFinal=stage===3&&Boolean(job.finalVideoUrl),media=showFinal?job.finalVideoUrl||'':mediaFor(scene)||job.thumbnailUrl||''
  const referencePreview=!showFinal&&!scene?.clipUrl&&Boolean(media),mediaVideo=showFinal||Boolean(scene?.clipUrl)||isVideo(media)
  const total=job.scenes.reduce((sum,item)=>sum+(item.durationSec||0),0),platforms=videoPlatforms(job.editor?.targetPlatforms,job.platform),locked=isSubmitting||busy||generating
  const status=generating?t('正在生成','Generating'):job.status==='failed'?t('需要处理','Needs attention'):job.status==='cancelled'?t('已停止','Stopped'):job.finalVideoUrl?t('成片可审核','Ready for review'):t('项目草稿','Project draft')

  useEffect(()=>{if(lastJobId.current===job.id)return;lastJobId.current=job.id;setEdits({});setLegacyRecovery({});setFeedbackByScene({});setSelectedId(job.scenes[0]?.id||'');setStage(job.finalVideoUrl?3:2);setConfirm(null);setError('');setCandidate(null)},[job.id])
  useEffect(()=>{if(!dirty)return;const warn=(event:BeforeUnloadEvent)=>{event.preventDefault();event.returnValue=''};window.addEventListener('beforeunload',warn);return()=>window.removeEventListener('beforeunload',warn)},[dirty])
  useEffect(()=>{if(!confirm)return;const previous=document.activeElement as HTMLElement|null,dialog=dialogRef.current;const buttons=()=>Array.from(dialog?.querySelectorAll<HTMLElement>('button:not([disabled]),textarea:not([disabled]),[tabindex="0"]')||[]);buttons()[0]?.focus();const key=(event:KeyboardEvent)=>{if(event.key==='Escape'){event.preventDefault();setConfirm(null)}if(event.key==='Tab'){const items=buttons(),first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}};dialog?.addEventListener('keydown',key);return()=>{dialog?.removeEventListener('keydown',key);previous?.focus()}},[confirm])
  const leave=(action:()=>void)=>{if(busy||isSubmitting)return;if(!dirty||window.confirm(t('有未保存修改，确定离开当前视图吗？修改会保留在本次会话中。','Leave this view with unsaved changes? Your draft will remain in this session.')))action()}
  const mutate=async(action:()=>MutationResult)=>{if(mutationLock.current)return false;mutationLock.current=true;setBusy(true);setError('');try{return (await action())!==false}catch(reason){setError(reason instanceof Error?reason.message:t('操作失败，请重试。','Unable to complete the action. Retry.'));return false}finally{mutationLock.current=false;setBusy(false);setConfirm(null)}}
  const choose=(id:string)=>{if(busy||id===selectedId)return;leave(()=>{setSelectedId(id);setStage(2);setConfirm(null);setCandidate(null)})}
  const restoreWorkspaceState=(saved:VideoWorkspaceState)=>{const restoredStage=restoreProductionVideoStage(saved.stage,Boolean(job.finalVideoUrl));if(restoredStage!==null)setStage(restoredStage===0?2:restoredStage);if(saved.selectedShotId&&job.scenes.some(item=>item.id===saved.selectedShotId))setSelectedId(saved.selectedShotId);if(saved.unsavedEdits){const next:Record<string,VideoShotEditorFields>={},recovery:Record<string,string>={},restoredFeedback:Record<string,VideoFeedback>={};for(const [id,snapshot] of Object.entries(saved.unsavedEdits)){const item=job.scenes.find(candidate=>candidate.id===id);if(!item)continue;const restored=restoreVideoEditorSnapshot(item,snapshot),baseline=sceneFields(item,readVideoShotTextState(item));if(!sameSceneFields(restored.fields,baseline))next[id]=restored.fields;if(restored.ambiguousLegacySubtitle)recovery[id]=restored.ambiguousLegacySubtitle;try{const value=videoRevisionInput(snapshot as VideoFeedback);if(value.reasons.length||value.note||value.instruction||value.candidateAdopted)restoredFeedback[id]=value}catch{}}setEdits(next);setLegacyRecovery(recovery);setFeedbackByScene(restoredFeedback)}}
