  const classify=async(choice:LegacyTextChoice)=>{if(!scene||!props.onClassifyLegacyText)return;await mutate(async()=>{const saved=await props.onClassifyLegacyText?.(scene.id,choice);if(saved===false)return false;setEdits(current=>{const next={...current};delete next[scene.id];return next});setLegacyRecovery(current=>{const next={...current};delete next[scene.id];return next});return true})}
  const regenerate=async()=>{if(!scene)return false;const storageKey=`video-render:${job.brandId}:${job.id}:${scene.id}`,prior=sessionStorage.getItem(storageKey);const request=prior?JSON.parse(prior):{...fields,...feedback,confirmed:true,requestKey:crypto.randomUUID()};sessionStorage.setItem(storageKey,JSON.stringify(request));const result=await props.onRegenerateScene(scene.id,{...request,reconcileOnly:Boolean(prior)});const outcome=typeof result==='object'?result.outcome:result===true?'completed':result==='failed'?'failed':'unknown';if(['completed','failed','not_submitted'].includes(outcome))sessionStorage.removeItem(storageKey);if(outcome==='failed')throw Error(t('重做已确认失败。再次尝试前需要重新确认费用。','The render failed. A new attempt requires a new cost confirmation.'));if(outcome==='not_submitted'){setError(typeof result==='object'&&result.error||t('尚未提交重做。处理提示后请重新确认费用。','No render was submitted. Resolve the issue and confirm the cost again.'));return false}if(outcome!=='completed')setError(t('重做结果待核对。重试会继续核对同一请求，不会另建付费任务。','The render result needs verification. Retry checks the same request without another paid task.'));return outcome==='completed'}
  const suggest=async()=>{if(!scene||!props.onRewriteScene)return;await mutate(async()=>{const result=await props.onRewriteScene!(scene.id,feedback.instruction||'');const spokenText=result.spokenText??result.voiceoverText??fields.spokenText;setCandidate({jobId:job.id,sceneId:scene.id,fields:{prompt:result.prompt??fields.prompt,spokenText,captionMode:spokenText.trim()?'mirror_spoken':'off',overlayText:result.overlayText??result.subtitle??fields.overlayText}})})}
  const sceneName=scene?.title||t(`分镜 ${index+1}`,`Scene ${index+1}`),reviewReady=!dirty&&!locked&&(!job.editor?.language||channelReady)
  const workspaceIds=new Set([...job.scenes.filter(fieldsChanged).map(item=>item.id),...Object.entries(feedbackByScene).filter(([,value])=>hasVideoFeedback(value)).map(([id])=>id)])
  const workspaceEdits=Object.fromEntries([...workspaceIds].map(id=>[id,{...(edits[id]||{}),...feedbackByScene[id]}]))
  const readyToAssemble=job.scenes.length>0&&job.scenes.every(item=>item.status==='ready')&&!job.finalVideoUrl&&!dirty&&!locked
  const sidebar=<><p className="pb-3 text-xs font-semibold text-slate-500">{t('分镜','Scenes')} · {job.scenes.length}</p>{job.scenes.map((item,itemIndex)=><button type="button" key={item.id} onClick={()=>choose(item.id)} aria-pressed={scene?.id===item.id&&!showFinal} aria-label={`${String(itemIndex+1).padStart(2,'0')} ${item.title||t('分镜','Scene')}`} className={`w-24 shrink-0 rounded-xl border bg-white p-1.5 text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-violet-500 lg:mb-3 lg:w-full ${scene?.id===item.id&&!showFinal?'border-violet-500 ring-1 ring-violet-400':'border-slate-200'}`}><div className="relative h-12 overflow-hidden rounded-lg bg-slate-100 lg:h-20">{mediaFor(item)?isVideo(mediaFor(item))?<video src={mediaFor(item)} muted playsInline preload="metadata" className="h-full w-full object-cover"/>:<img src={mediaFor(item)} alt="" className="h-full w-full object-cover"/>:<Clapperboard className="m-auto h-full w-5 text-slate-300"/>}<span className="absolute bottom-1 left-1 rounded bg-black/60 px-1 text-[10px] text-white">{String(itemIndex+1).padStart(2,'0')}{item.durationSec?` · ${item.durationSec}s`:''}</span></div><div className="mt-1 flex items-center justify-between gap-1 text-[11px]"><span className="truncate">{item.title||t(`分镜 ${itemIndex+1}`,`Scene ${itemIndex+1}`)}</span>{changed(item)?<span aria-label={t('有未保存修改','Has unsaved changes')} className="h-2 w-2 rounded-full bg-amber-500"/>:item.status==='ready'?<Check className="h-3 w-3 shrink-0 text-emerald-600"/>:item.status==='failed'?<AlertCircle className="h-3 w-3 shrink-0 text-rose-600"/>:null}</div></button>)}{!job.scenes.length&&<p className="p-2 text-xs text-slate-400">{t('等待分镜','Waiting for scenes')}</p>}</>
